    isPremium: true,
    description: 'Jeden Samstag von 9 bis 14 Uhr treffen sich Markthändler, Einheimische sowie Touristen auf dem Wochenmarkt in Winterberg. Der Marktplatz an der Unteren Pforte lädt zum gemütlichen Bummeln mit der Familie und Freunden ein. Stöbern Sie nach Waren aller Art! Ob knackiges Obst und Gemüse, leckere Südfrüchte, frischer Fisch, Textilien und Lederwaren oder Holzartikel – hier bleiben wenig Wünsche offen! Verköstigt werden Sie am Imbiss mit feinen Suppen, Bratwürsten und anderen Leckereien. Besuchen Sie den Wochenmarkt in Winterberg und treffen Sie auf altbekannte und neue Gesichter!',
    extendedDescription: 'Der Wochenmarkt in Winterberg ist der beliebte wöchentliche Treffpunkt im Zentrum der Stadt. Jeden Samstag von 9:00 bis 14:00 Uhr verwandelt sich der Marktplatz an der Unteren Pforte in eine bunte Marktmeile. Hier bieten regionale Erzeuger und Händler frische Lebensmittel wie Obst, Gemüse, Südfrüchte, Käse und fangfrischen Fisch an. Ergänzt wird das Sortiment durch handwerkliche Holzartikel, Textilien, Lederwaren und saisonale Spezialitäten. Für das leibliche Wohl sorgt der traditionelle Marktimbiss mit herzhaften Suppen, Bratwürsten und weiteren Köstlichkeiten.',
